// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy == dummy);
        uint256 shares;
        uint256 baseInput;
        uint256 quoteInput;
        try c.buyShares(address(this)) returns (uint256 __r0, uint256 __r1, uint256 __r2) { shares = __r0; baseInput = __r1; quoteInput = __r2; } catch { return; }
        assertTrue(c.totalSupply() >= shares);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
